import{_ as e,o as r,c as a,a2 as l}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"실시간 진형·카드 전투","description":"","frontmatter":{},"headers":[],"relativePath":"rules/Realtime-Formation-Card-Battle.md","filePath":"rules/Realtime-Formation-Card-Battle.md"}'),d={name:"rules/Realtime-Formation-Card-Battle.md"};function o(i,t,n,s,c,h){return r(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="실시간-진형·카드-전투" tabindex="-1">실시간 진형·카드 전투 <a class="header-anchor" href="#실시간-진형·카드-전투" aria-label="Permalink to &quot;실시간 진형·카드 전투&quot;">​</a></h1><p><img src="https://github.com/islee23520/seoul-kenshi/blob/main/docs/assets/wiki/isometric-realtime-formation-card-battle.svg?raw=true" alt="한 판의 실시간 진형 카드 전투 위치 방향 시야 규칙"></p><p>여기서 한 판은 확정된 전투 컨텍스트로 시작해 ResultId 하나로 끝나는 실시간 진형·카드 전투 세션 한 번을 뜻합니다. 한 판 안에서 진형·사기·카드 타이밍이 실시간 전술의 핵심 축이며, 위치·방향·시야는 진형 규칙으로 이어집니다.</p><blockquote><p>2026-09-07 소유자 결정(<a href="https://github.com/islee23520/seoul-kenshi/blob/main/Intent.md" target="_blank" rel="noreferrer">Intent</a> 결정 3)으로 전투는 턴제 SRPG에서 <strong>실시간 진형·카드 전투</strong>로 확정되었습니다. 이 문서는 승인된 게임 Core 계약을 정의합니다. 현재 런타임은 실시간 전환 단계에 있으며 인물별 카드 소유권과 판정(작업 5)의 결함 수정(명령 별칭, 증원 카드, 소유자 HUD, 캠페인 필터)이 진행 중입니다. 분대 이동과 공격 명령(작업 6), 집계 사상자 표현(작업 7)은 승인된 설계 계약이며 아직 구현 완료 상태가 아닙니다. 목표 형태의 근거는 <a href="/rules/Ref-Songs-of-Silence.html">Songs of Silence</a>와 <a href="/rules/Ref-Ravelen-Chronicles.html">라벨렌 전기</a> 조사입니다.</p></blockquote><h2 id="탐색과-같은-문법" tabindex="-1">탐색과 같은 문법 <a class="header-anchor" href="#탐색과-같은-문법" aria-label="Permalink to &quot;탐색과 같은 문법&quot;">​</a></h2><p>전투에 들어가도 카메라나 공간 규칙은 바뀌지 않습니다. 탐색에 쓰던 고정 직교 아이소메트릭 카메라와 1.5m 4방향 타일 격자 위에서 진형이 배치되고 시간은 30Hz 고정 틱으로 흐릅니다. 런타임에서는 D1 드라이버가 프레임당 최대 4스텝을 진행합니다. 일시정지는 시뮬레이션 명령이 아니며 해시 입력에서 제외됩니다. 전투 초기화는 정산 전에 현재 전투만 시작 상태로 되돌리며, 캠페인 진행이나 이미 반영한 정산을 되돌리지 않습니다.</p><h2 id="플레이어가-하는-일" tabindex="-1">플레이어가 하는 일 <a class="header-anchor" href="#플레이어가-하는-일" aria-label="Permalink to &quot;플레이어가 하는 일&quot;">​</a></h2><p>플레이어는 개별 병사를 직접 조작하지 않고 분대 단위 명령과 카드 타이밍을 다룹니다.</p><ol><li><strong>전투 전 진형 편집</strong>: 전열, 후열, 측면에 분대를 배치하고 4방향 정면을 정합니다. 리더의 지휘 반경(3칸) 안에 있는 인물만 카드와 협공 대상이 됩니다.</li><li><strong>전투 중 카드 발동</strong>: 인물별 카드 <code>(OwnerUnitId, CardId)</code>와 출격 전 선택한 거점 카드(최대 2장)를 각 카드의 재충전 주기에 맞춰 냅니다. 기동 재집결은 600틱이며, 전체 카드의 재충전은 300~900틱입니다. 덱 구축이나 무작위 드로우는 없습니다.</li><li><strong>분대 지시와 제어</strong>: actor 기반 분대 이동(Move), 목표 적 지정 공격(Attack), 방향 전환(SetFacing)을 내립니다. 일시정지, 줌, 전투 리셋으로 전황을 통제합니다.</li><li><strong>후퇴 및 항복 판단</strong>: 사기 경고선을 넘기기 전에 물러나거나, 적 사기가 20 이하이고 지휘관 HP가 50% 이하이며 퇴로가 열린 조건에서 항복을 받아냅니다. 지휘관 타일 점거는 퇴로 차단과 같지 않습니다.</li></ol><h2 id="승인된-core-계약" tabindex="-1">승인된 Core 계약 <a class="header-anchor" href="#승인된-core-계약" aria-label="Permalink to &quot;승인된 Core 계약&quot;">​</a></h2><h3 id="a-인물-카드-소유권과-명령-계약" tabindex="-1">A. 인물 카드 소유권과 명령 계약 <a class="header-anchor" href="#a-인물-카드-소유권과-명령-계약" aria-label="Permalink to &quot;A. 인물 카드 소유권과 명령 계약&quot;">​</a></h3><ul><li><strong>카드 상태 분리</strong>: 인물 카드는 <code>(OwnerUnitId, CardId)</code> 쌍으로 상태를 관리하며 소유자마다 독립된 재충전 타이머를 가집니다. 재충전 길이는 기존 카드별 값을 유지합니다: 방패벽 300틱, 격려 600틱, 협공 450틱, 기동 재집결 600틱. 공유 거점 카드인 보급과 통행은 각각 900틱과 750틱입니다.</li><li><strong>명령 주체 명시</strong>: 분대 명령(Move, Attack, SetFacing)은 실행 주체(<code>actor</code>)와 목표 위치 또는 대상 <code>UnitId</code>를 명확히 지정합니다.</li><li><strong>거점 카드 공유</strong>: 거점 카드는 최대 2슬롯이며 아군 분대 전체가 공유합니다.</li><li><strong>순수 판정과 실행 분리</strong>: 미리보기(Preview)는 상태를 변경하지 않는 순수 판정으로 동작합니다. 확정(Submit) 시점에 유효성을 다시 검증하고 한 번만 반영합니다.</li><li><strong>리플레이 버전 관리</strong>: 규칙 버전을 명확히 구분하며 이전 소유자 없는 리플레이(ownerless replay)는 재생 전 버전 오류를 명시해 거부합니다. 원본 파일 자동 변환이나 삭제는 하지 않습니다.</li></ul><h3 id="b-집계-생존수와-사상자-계약" tabindex="-1">B. 집계 생존수와 사상자 계약 <a class="header-anchor" href="#b-집계-생존수와-사상자-계약" aria-label="Permalink to &quot;B. 집계 생존수와 사상자 계약&quot;">​</a></h3><ul><li><strong>분대 구성과 뷰</strong>: 초기 편성은 양측 6개 논리 분대(총 12분대)이며 증원은 별도로 추가됩니다. 각 분대는 4명의 병사 뷰와 1명의 중앙 리더로 표현됩니다. 리더는 연출용이며 별도 전투 HP나 정산 ID를 갖지 않습니다.</li><li><strong>0..4 집계 생존수</strong>: 초기 생존수는 <code>ceil(4 * 시작Hp / MaxHp)</code>로 정합니다(Hp가 0이면 0). 이후에는 아래 피해 규칙으로 갱신한 집계 상태를 표시하며, 매번 현재 HP로 다시 계산해 치료를 부활로 바꾸지 않습니다.</li><li><strong>단조 감소</strong>: 피해를 입을 때 생존 수는 <code>min(이전 생존수, ceil(4 * 현재Hp / MaxHp))</code>로 줄어들며 치료를 받아도 쓰러진 병사가 부활하지 않습니다.</li><li><strong>독립 증원</strong>: 증원 병력은 기존 분대의 인원 회복이 아니라 고유 초기 HP를 가진 별도 분대로 전장에 진입합니다.</li><li><strong>정산 불변</strong>: 정산과 결과 기록은 기존 논리 <code>UnitId</code>와 남은 <code>HP</code>를 기준으로 단 1회(exactly-once) <code>ResultId</code>와 함께 확정됩니다.</li></ul><h2 id="잠긴-수치" tabindex="-1">잠긴 수치 <a class="header-anchor" href="#잠긴-수치" aria-label="Permalink to &quot;잠긴 수치&quot;">​</a></h2><p>다음 값은 <code>BattleRules</code>와 같은 계약 수치입니다. 문서와 구현이 다르면 구현의 같은 이름 상수를 우선 확인하고 이 표를 함께 고칩니다.</p><table tabindex="0"><thead><tr><th>name</th><th style="text-align:right;">value</th><th>unit</th></tr></thead><tbody><tr><td>TicksPerSecond</td><td style="text-align:right;">30</td><td>Hz</td></tr><tr><td>MoveTicksPerCell</td><td style="text-align:right;">10</td><td>ticks per cell</td></tr><tr><td>AttackCooldownTicks</td><td style="text-align:right;">30</td><td>ticks</td></tr><tr><td>MoraleBase</td><td style="text-align:right;">60</td><td>morale</td></tr><tr><td>MoraleWarn</td><td style="text-align:right;">40</td><td>morale</td></tr><tr><td>MoraleRecoverCap</td><td style="text-align:right;">80</td><td>morale</td></tr><tr><td>MoraleRecoveryPerSecond</td><td style="text-align:right;">5</td><td>morale per second</td></tr><tr><td>MoraleLossPerDeath</td><td style="text-align:right;">5</td><td>morale</td></tr><tr><td>MoraleLossCommanderBelowHalf</td><td style="text-align:right;">10</td><td>morale</td></tr><tr><td>SurrenderMoraleMax</td><td style="text-align:right;">20</td><td>morale</td></tr><tr><td>SurrenderCommanderHpPercentMax</td><td style="text-align:right;">50</td><td>percent</td></tr><tr><td>StrongholdCardSlots</td><td style="text-align:right;">2</td><td>slots</td></tr><tr><td>CardEffectTicks</td><td style="text-align:right;">150</td><td>ticks</td></tr><tr><td>MaxTicks</td><td style="text-align:right;">9000</td><td>ticks</td></tr><tr><td>CommandRadius</td><td style="text-align:right;">3</td><td>cells</td></tr><tr><td>RulesVersion</td><td style="text-align:right;">rtfc-owner-cards-v2</td><td>version</td></tr></tbody></table><p>항복은 사기 20 이하, 지휘관 HP 50% 이하, 퇴로 확보가 모두 참일 때만 성립합니다. 여기서 지휘관 타일 점거는 퇴로 차단과 같지 않습니다.</p><h2 id="전투에서-다루는-것" tabindex="-1">전투에서 다루는 것 <a class="header-anchor" href="#전투에서-다루는-것" aria-label="Permalink to &quot;전투에서 다루는 것&quot;">​</a></h2><ul><li>진형(전열, 후열, 측면)과 4방향 정면, 지휘 반경(3칸)</li><li>6v6 논리 분대(분대당 4병사 뷰와 중앙 리더)</li><li>사기 게이지, 기본 60, 경고 40, 회복 상한 80, 항복 판정 상한 20</li><li>인물 카드(관계, 생업, 특기)와 거점 카드(보급, 통행권, 설비)</li><li>지형 비용과 엄폐, 장치(수문, 문, 신호) 조작</li><li>예고된 증원 위치와 위협 표시</li><li>부상, 쓰러짐, 포획, 후퇴, 항복과 사망</li><li>일시정지, 시점 줌, 전투 시작 상태로의 리셋. 일시정지는 시뮬레이션 명령이 아니며 해시에 들어가지 않습니다</li></ul><h2 id="전장의-기본-형태" tabindex="-1">전장의 기본 형태 <a class="header-anchor" href="#전장의-기본-형태" aria-label="Permalink to &quot;전장의 기본 형태&quot;">​</a></h2><table tabindex="0"><thead><tr><th>원형</th><th>전술 특징</th></tr></thead><tbody><tr><td>작은 역사</td><td>기둥과 상점, 짧은 교전 거리, 좁은 전열</td></tr><tr><td>환승역</td><td>층 전환, 여러 입구, 측면 노출과 증원 경로</td></tr><tr><td>종착역</td><td>막힌 끝, 넓은 승강장, 차량 엄폐</td></tr><tr><td>터널</td><td>한 줄 진형, 긴 시야, 퇴로 위험</td></tr><tr><td>지상 폐허</td><td>넓은 시야, 환경 노출, 기동 카드 유리</td></tr><tr><td>차량기지 인접</td><td>대형 설비, 수리 목표, 다중 경로</td></tr><tr><td>한강 횡단 구간</td><td>제한된 연결, 붕괴와 침수 위험</td></tr></tbody></table><h2 id="같은-상황은-같은-결과로" tabindex="-1">같은 상황은 같은 결과로 <a class="header-anchor" href="#같은-상황은-같은-결과로" aria-label="Permalink to &quot;같은 상황은 같은 결과로&quot;">​</a></h2><p>실시간 환경에서도 결정론 계약은 엄격히 유지됩니다. 전장 생성, 명중, 피해, 사기, 증원과 카드 플레이는 전투 시드와 틱 스탬프가 붙은 명령 기록으로 완벽히 재현되어야 합니다.</p><ul><li>시뮬레이션은 30Hz 고정 간격으로 진행됩니다.</li><li>D1 드라이버만 <code>BattleSim.Step</code>을 호출하며 한 프레임에 최대 4스텝까지 처리합니다.</li><li>UI의 시각 이동(Transform)은 게임 Core의 논리 위치를 따라 표현합니다. 화면에서만 분대를 이동시켜 Core의 이동 판정을 대신하지 않습니다.</li><li>동일한 입력 기록이 다른 결과를 내면 검증 실패입니다.</li></ul><h2 id="현재-구현-상태와-계약-경계" tabindex="-1">현재 구현 상태와 계약 경계 <a class="header-anchor" href="#현재-구현-상태와-계약-경계" aria-label="Permalink to &quot;현재 구현 상태와 계약 경계&quot;">​</a></h2><ul><li><strong>Core 계약 승인</strong>: A(인물별 카드 소유권 및 명령)와 B(0..4 집계 생존수) 계약이 승인되어 본 문서에 반영되었습니다.</li><li><strong>작업 5 원본 검증 완료, 후속 수정 별도</strong>: 인물별 카드 소유권과 순수 판정 로직의 원본 62개 사례는 회귀 소스 해시와 함께 검증되었습니다. 이후 소유자 상대 지휘 반경을 고친 Core 레인에서는 해당 변경에 대해 1개 RED/GREEN 사례가 확인되었습니다. 최초 진형 버튼의 Raycast/EventSystem 이슈는 아직 해결되지 않았습니다.</li><li><strong>작업 6 검증 상태 보류</strong>: 이전 69개 GREEN 결과는 추가 4개 반례 테스트 전의 결과이며, 최종 11개 범주 결과는 pending입니다. 분대 Move/Attack 및 방향 명령은 승인된 계약이지만 구현 완료로 표시하지 않습니다.</li><li><strong>작업 7 미완료</strong>: 집계 생존수 및 사상자 처리는 승인된 계약이며 구현 완료되지 않았습니다.</li><li><strong>입력·자산 경계</strong>: Foundation raycast depth -1 원인은 아직 해결되지 않았습니다. 원본 SVG는 사용 가능 후보로 구분되지만, 그 사실이 캐릭터·타이틀·아이콘·역사 텍스처의 rights/look 검토 차단을 해소하지 않습니다.</li></ul>',27)])])}const m=e(d,[["render",o]]);export{u as __pageData,m as default};
